/* Common role weights must outrank product resets and generated literal weights.
   This unlayered bridge keeps the component owner effective in Tailwind and
   non-Tailwind apps. Product inline adapters already use these same variables. */
html .qd-btn, html .qd-field-label, html .qd-control-label { font-weight: var(--qd-font-weight-medium); }
html .qd-card-title, html .qd-dialog-title, html .qd-drawer-title { font-weight: var(--qd-font-weight-semibold); }
